	('49791796-b9a7-4bbd-906c-7808de6da5b0', NULL, 'Use "Not only...but also" inversion', 'Student can form emphatic sentences with not only/but also inversion.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('e77ce65c-9c2d-4f62-8e0f-0087a07bfa43', NULL, 'Use emphatic do and cleft sentences', 'Student can add emphasis with "do" and cleft sentence structures.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('34c5cd56-2dfd-44e2-861b-85d889e425d8', NULL, 'Use sophisticated idioms', 'Student can interpret and use advanced idioms correctly.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('66617e32-e81b-45aa-a562-5dda22520bd2', NULL, 'Use natural word collocations', 'Student can identify and use natural collocations over unnatural word pairings.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('cbcbdfcc-3265-43ae-acd5-0af6b36a10dd', NULL, 'Infer idiom meaning from context', 'Student can infer the meaning of idioms/collocations heard in natural speech.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('cb76120d-75cf-47b9-ad6b-1c80b490e63f', NULL, 'Write in impersonal academic style', 'Student can rewrite personal opinions as impersonal academic statements.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('f10bbc93-6fa7-47dd-9722-cdf244282570', NULL, 'Use hedging language', 'Student can soften claims using appropriate hedging phrases.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('7a44dcca-fc80-4b8f-b7f6-639b4c2d322d', NULL, 'Write a formal academic paragraph', 'Student writes a paragraph combining impersonal style and hedging.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('4ec1ebbb-8f09-45ae-a533-88ecd5ecca26', NULL, 'Use formal inverted conditionals', 'Student can form Were I to.../Should you... inverted conditionals.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('3b0455f5-0459-4f9b-865c-909fe5d44317', NULL, 'Use inverted third conditionals', 'Student can form Had it not been for.../Had I known... sentences.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('24edda40-1d1c-4ae6-8c08-b69542383bbe', NULL, 'Write with complex conditionals', 'Student writes a formal passage using inverted conditional structures.', 'published', '2026-07-07 12:20:53.673728+00', '2026-07-07 12:20:53.673728+00'),
	('2f8072dc-6320-40f5-80d2-a7283a4ec108', NULL, 'Use nuanced hedging devices', 'Student can soften claims using varied, precise hedging language.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('9b439585-84ce-417f-b064-29c35b51d88c', NULL, 'Disagree diplomatically', 'Student can use softened language to express diplomatic disagreement.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('b405012e-3c25-4c37-b0b3-b5291580f9ff', NULL, 'Understand nuanced spoken disagreement', 'Student can identify real positions behind diplomatically hedged language.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('38465254-6929-4fac-bef3-3d37b7e5748a', NULL, 'Use reference devices for cohesion', 'Student can use this/that/such/the former to link paragraphs.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('cf49985b-a9e4-4ce6-9f43-0ca398574644', NULL, 'Vary linking devices across a text', 'Student can revise text to use varied, non-repetitive linking devices.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('807d7d8f-ecae-4a0a-b004-ef48b3f87771', NULL, 'Write a cohesive multi-paragraph text', 'Student writes 3 paragraphs that stay cohesive using reference and linking devices.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('847c796a-fe21-469c-980e-7abd3c5acba6', NULL, 'Use idioms fluently in conversation', 'Student can weave idioms/collocations naturally into spoken responses.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('11ed8c45-be60-4721-b172-48c7eb422049', NULL, 'Use idioms/collocations in professional writing', 'Student can select appropriately semi-formal idioms/collocations for writing.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('da993437-dbcb-4013-af34-23d6201dcc0a', NULL, 'Understand idiom-dense fluent speech', 'Student can extract overall meaning from idiom-dense native speech.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('b2ecfed7-2df9-45d5-b2ee-3c6b7345e63b', NULL, 'Build a persuasive argument', 'Student can structure a spoken argument using persuasive techniques.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00');
INSERT INTO public.objectives (id, key, title, description, status, created_at, updated_at) VALUES
	('3d913846-a524-4486-808e-756c58ccca29', NULL, 'Rebut opposing views persuasively', 'Student can anticipate and persuasively rebut a counterargument.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('bca1a1ad-09c9-4ca2-a6f0-4f72b876feef', NULL, 'Deliver a persuasive speech', 'Student delivers a structured persuasive speech with a rebuttal.', 'published', '2026-07-07 12:23:17.718196+00', '2026-07-07 12:23:17.718196+00'),
	('a40c88f2-8f5d-4b01-baf4-7e8e418e06c3', NULL, 'Write an arguable thesis statement', 'Student writes a clear, debatable thesis for an essay topic.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('7597566e-5e16-4d71-b8af-c65523fbc8f1', NULL, 'Write a counterargument and rebuttal', 'Student writes a paragraph that fairly presents and rebuts an opposing view.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('bc33326b-bf4d-4855-a733-8b91ea31f543', NULL, 'Write a complete argumentative essay', 'Student writes a full essay with thesis, body, counterargument/rebuttal, and conclusion.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('b967e685-5887-4839-8a6e-86fb2c41b498', NULL, 'Maintain consistent academic register', 'Student rewrites an informal paragraph in consistent academic register.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('a3878ef9-04a5-4ff1-a228-9b7bef72fed4', NULL, 'Hedge claims consistently across a text', 'Student revises multiple claims in a text with consistent, appropriate hedging.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('0f9f537b-b471-4522-b585-577a75ff212d', NULL, 'Write a fully formal, hedged essay', 'Student writes an essay maintaining formal register and hedging throughout.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('097b6ba0-e830-4a16-ba89-f8f2b74489e9', NULL, 'Identify multiple perspectives fairly', 'Student can summarize 2-3 distinct viewpoints on an issue accurately.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('fd6aaf6a-bc48-4579-ba41-2f9a9fc9a9fb', NULL, 'Write a synthesis paragraph', 'Student combines multiple perspectives into one coherent paragraph.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('6781925c-3015-4c13-a75c-01055ac47a8f', NULL, 'Write a full synthesis essay', 'Student writes a full essay synthesizing multiple perspectives into a reasoned conclusion.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('52882120-f54d-4565-9f67-7aacab829bba', NULL, 'Cut unnecessary wordiness', 'Student can identify and remove redundant words/phrases.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('82e46259-b420-4cd5-8731-db76cb639c63', NULL, 'Strengthen cohesion without adding wordiness', 'Student revises a choppy paragraph to flow smoothly and concisely.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('9b1db291-9765-4d31-9a7f-ee8c57246d74', NULL, 'Produce a fully polished final essay', 'Student edits a rough draft into a polished, cohesive, concise final essay.', 'published', '2026-07-07 12:26:22.662421+00', '2026-07-07 12:26:22.662421+00'),
	('2a888bb1-b41c-42cc-97b1-39c21e3a7ee1', NULL, 'Shift register naturally within a conversation', 'Student can produce natural register shifts within a single exchange.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('3fec3a6c-bea1-4c41-a16a-7b9eafaea995', NULL, 'Adjust idiom density for context', 'Student can adapt idiom use appropriately across social and professional contexts.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('88fd58dc-e794-4ffb-b750-4c4475085745', NULL, 'Understand native register shifts', 'Student can identify register shifts and their social meaning in extended native speech.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('bc980de9-6ebe-4023-a582-2112fbffee3f', NULL, 'Interpret implication beyond literal meaning', 'Student can explain the implied meaning behind indirect statements.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('e53f2349-c309-4f53-b3cf-703ab278f83b', NULL, 'Use understatement effectively', 'Student can produce appropriate understatement for strong situations.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('07036bf4-dc82-4e4d-a6c3-b281150ea0ff', NULL, 'Control tone through modal choice', 'Student can select modal verbs to precisely convey intended tone.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('9922e47b-7bac-45a0-adf4-32a407c1869c', NULL, 'Identify irony and metaphor', 'Student can identify and interpret irony and metaphor in an authentic text.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('a2b41834-0e90-495e-8fde-efeffd8f56ef', NULL, 'Identify allusion and rhetorical questions', 'Student can identify allusion and rhetorical questions and explain their effect.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('1fd5a59a-475b-45c1-9c77-af364f411c77', NULL, 'Interpret devices in an extended authentic passage', 'Student can identify and interpret multiple literary/rhetorical devices across a longer text.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('9c4621af-6d63-41bc-937d-268758096ca4', NULL, 'Follow a natural-pace unscripted interview', 'Student can extract the speaker''s real points from natural, hesitant speech.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('7704cfde-850b-4d33-8995-c846c78e3d12', NULL, 'Follow an extended multi-speaker discussion', 'Student can track multiple speakers'' positions across an extended discussion.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00'),
	('765b0b4b-9837-4c2e-bad3-372de37acb28', NULL, 'Summarize an extended listening passage', 'Student produces an accurate, concise summary of a long, complex passage.', 'published', '2026-07-07 17:22:51.837819+00', '2026-07-07 17:22:51.837819+00');
