INSERT INTO public.question_bank (id, type, stem, rich_stem, difficulty, explanation, hint, tags, status, created_by, created_at, updated_at, listening_script) VALUES
	('0b68937d-c954-419f-ab72-fb8ad8aeb707', 'true_false', '"Bye" is a way to say goodbye.', NULL, 'beginner', 'True — "bye" is a casual goodbye.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('ab000000-0000-0000-0001-000000000001', 'multiple_choice', 'She _____ a student.', NULL, 'beginner', 'We use "is" with he/she/it.', 'Think about the subject — she is third person singular.', '{a1,grammar,to_be}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000002', 'multiple_choice', 'What is the opposite of "big"?', NULL, 'beginner', 'Big means large. The opposite is small.', 'Think about size.', '{a1,vocabulary}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000003', 'true_false', '"I have a apple" is correct English.', NULL, 'beginner', 'We use "an" before vowel sounds: an apple.', 'Check the article before "apple".', '{a1,grammar,articles}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000004', 'fill_in_the_blank', 'My _____ is Ahmed. (name / game)', NULL, 'beginner', 'We say "My name is..." to introduce ourselves.', 'How do you introduce yourself?', '{a1,vocabulary,greetings}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000005', 'multiple_choice', 'They _____ to school every day.', NULL, 'beginner', 'With they/we/I/you, use the base form: go.', 'They is plural — no -s needed.', '{a1,grammar,present_simple}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000006', 'multiple_choice', 'The book is _____ the table.', NULL, 'beginner', '"On" means touching the surface.', 'The book is resting on top of something.', '{a1,grammar,prepositions}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000007', 'multiple_choice', 'How many letters are in the English alphabet?', NULL, 'beginner', 'The English alphabet has 26 letters: A-Z.', 'Count from A to Z.', '{a1,phonics}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000008', 'multiple_choice', 'My mother''s mother is my _____.', NULL, 'beginner', 'Your mother''s mother is your grandmother.', 'Think about family relationships.', '{a1,vocabulary,family}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000009', 'true_false', '"She go to school" is correct.', NULL, 'beginner', 'Third person singular needs -s: She goes to school.', 'Check the verb with she/he/it.', '{a1,grammar,present_simple}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0001-000000000010', 'multiple_choice', 'What color is the sky on a clear day?', NULL, 'beginner', 'A clear sky is blue.', 'Look up!', '{a1,vocabulary,colors}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0002-000000000001', 'multiple_choice', 'She _____ to the park yesterday.', NULL, 'elementary', '"Go" becomes "went" in past simple (irregular).', 'Yesterday = past tense.', '{a2,grammar,past_simple}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0002-000000000002', 'multiple_choice', 'This book is _____ than that one.', NULL, 'elementary', 'Use "more interesting" for long adjectives.', 'Long adjectives use "more" for comparatives.', '{a2,grammar,comparatives}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0002-000000000003', 'fill_in_the_blank', 'I _____ TV when my friend called. (watch — past continuous)', NULL, 'elementary', 'Past continuous: was/were + verb-ing.', 'What tense shows an action in progress in the past?', '{a2,grammar,past_continuous}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0002-000000000004', 'multiple_choice', 'Choose the word for "a person who serves food in a restaurant".', NULL, 'elementary', 'A waiter/waitress serves food.', 'Think about restaurant workers.', '{a2,vocabulary}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0002-000000000005', 'true_false', '"I am go to the shop now" is correct present continuous.', NULL, 'elementary', 'Present continuous: am/is/are + verb-ing. Correct: I am going.', 'Check the -ing form.', '{a2,grammar,present_continuous}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0003-000000000001', 'multiple_choice', 'I have _____ to London three times.', NULL, 'intermediate', 'Present perfect with "been" for experiences.', 'Have + past participle.', '{a3,grammar,present_perfect}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0003-000000000002', 'multiple_choice', 'If I _____ more time, I would travel more.', NULL, 'intermediate', 'Second conditional: If + past simple, would + base verb.', 'This is an unreal/imaginary situation.', '{a3,grammar,conditionals}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0003-000000000003', 'multiple_choice', 'The report _____ by the manager last week.', NULL, 'intermediate', 'Past passive: was/were + past participle.', 'Who did the action? The manager. The report received the action.', '{a3,grammar,passive}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0003-000000000004', 'multiple_choice', 'The man _____ lives next door is a teacher.', NULL, 'intermediate', 'Use "who" for people in defining relative clauses.', 'Which word connects a person to extra information?', '{a3,grammar,relative_clauses}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('ab000000-0000-0000-0003-000000000005', 'multiple_choice', 'She enjoys _____. (swim / swimming / to swim)', NULL, 'intermediate', 'After "enjoy" we use the gerund (-ing form).', 'Some verbs are followed by -ing.', '{a3,grammar,gerunds}', 'published', '00000000-0000-0000-0000-000000000001', '2026-06-27 00:03:15.983287+00', '2026-06-27 00:03:15.983287+00', NULL),
	('d008ddae-0930-438c-a6b5-17d9cb00383d', 'multiple_choice', 'Which letter comes after "C" in the alphabet?', NULL, 'beginner', '"D" comes right after "C": A, B, C, D.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('a87de588-9b7f-4351-bedf-3a18b34ebfed', 'true_false', '"Z" is the last letter of the English alphabet.', NULL, 'beginner', 'The alphabet ends with Z.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('54ee6378-c771-4777-ba10-c5d5790c20c0', 'fill_in_the_blank', 'Fill in the missing letter: A, ___, C, D', NULL, 'beginner', 'The alphabet order is A, B, C, D.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('e7fe926e-473b-4c0d-8017-0438026d38ed', 'multiple_choice', 'Which word has the short "a" sound, like in "cat"?', NULL, 'beginner', '"Hat" has the same short "a" sound as "cat".', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('52c25ab4-e888-427e-8da1-2f8725c67c0a', 'multiple_choice', 'Which word has the short "i" sound, like in "sit"?', NULL, 'beginner', '"Sit" and "bit" share the short "i" sound.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('cf43d4e0-36f8-49e5-aca6-7671c3d270d4', 'true_false', 'The word "hot" has a short "o" sound.', NULL, 'beginner', 'Correct, "hot" has the short "o" sound.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('c8160e75-f5c7-479f-a696-9654a66a53cc', 'listening_choice', 'Listen. Which word did you hear: "pat" or "bat"?', NULL, 'beginner', 'The speaker said "bat" — notice the "b" sound.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Listen carefully: Bat.'),
	('a3c39ac3-a02f-4ae1-9770-b48766ce3906', 'multiple_choice', 'Which pair of words differ only by their first consonant sound (p vs b)?', NULL, 'beginner', '"Pig" and "big" differ only by the initial p/b sound.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('fb67abc9-ba75-4533-add4-07d3188d880d', 'multiple_choice', 'Which word starts with the blend "st"?', NULL, 'beginner', '"Stop" starts with the "st" blend.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('e7a6bed2-135d-44bf-8780-df73384d3036', 'listening_choice', 'Listen to the word. Does it start with a blend?', NULL, 'beginner', '"Train" starts with the "tr" blend — yes.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Listen: Train.'),
	('02db22f1-b409-4c56-9352-e1794e59ebc6', 'listening_choice', 'Listen to the command. What should you do?', NULL, 'beginner', 'The command "Open your book" means take out your book and open it.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Open your book.'),
	('fe256f96-db64-4eac-9da0-90d1494d0ca9', 'listening_choice', 'Listen to the command. What is being asked?', NULL, 'beginner', '"Repeat after me" asks you to say the same words back.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Repeat after me.'),
	('a473d283-47bb-4a03-bd72-baf1e6556caa', 'true_false', '"Listen" means you should read out loud.', NULL, 'beginner', 'False — "Listen" means to pay attention with your ears, not read aloud.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('a3d9c78e-ddaf-45b7-9a10-1e95d9fa87e1', 'multiple_choice', 'What number is "seven"?', NULL, 'beginner', 'Seven is the number 7.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('1bbc3aaa-5652-45a8-978d-03f106b3ee98', 'multiple_choice', 'How do you say "15" in English?', NULL, 'beginner', '15 is "fifteen".', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('4ab07406-4006-41e6-8d8f-de3438645b83', 'fill_in_the_blank', 'Write the number word for 12.', NULL, 'beginner', '12 is spelled "twelve".', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('ef8ddb1c-105a-4b62-b4a1-a10d7a9ff2c8', 'listening_choice', 'Listen to the number. Which one did you hear?', NULL, 'beginner', 'The speaker said "eighteen" (18).', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Eighteen.'),
	('b58ed4d9-aa17-4a68-9dd7-cd326e725991', 'true_false', '"Zero" means the number 0.', NULL, 'beginner', 'True — zero is 0.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('285b5360-077d-4b3a-a43f-f866a0b72147', 'multiple_choice', 'Which greeting is correct in the morning?', NULL, 'beginner', '"Good morning" is used before noon.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('03e7e43f-1f4d-4373-ac85-611b0be40804', 'listening_choice', 'Listen. What greeting did you hear?', NULL, 'beginner', 'The speaker said "Good evening".', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Good evening!'),
	('dc0f30b5-a50d-4493-942f-164e29886b52', 'multiple_choice', 'What do you say after someone helps you?', NULL, 'beginner', '"Thank you" is the correct response.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('e07beb14-2cdd-4161-85b5-1a879a8f49c2', 'multiple_choice', 'What do you say when you bump into someone by accident?', NULL, 'beginner', '"Sorry" or "Excuse me" are polite responses.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('e9e4482d-fe0f-4696-b4a7-43c2eb33848b', 'fill_in_the_blank', 'Complete the phrase: "___, can you help me?" (a polite word to get attention)', NULL, 'beginner', '"Excuse me" is used to politely get someone''s attention.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('6724f23a-002c-4822-a4c3-9fc6111284ce', 'fill_in_the_blank', 'Complete: "My ___ is Ana."', NULL, 'beginner', '"My name is Ana" is the correct introduction.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('fb531681-ae13-49d6-a4dc-c187ca2a6c09', 'multiple_choice', 'How do you ask someone''s name?', NULL, 'beginner', '"What is your name?" is the correct question.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('986b9255-963b-4f5f-9851-d5dc6540bd82', 'listening_choice', 'Listen to the introduction. What is the speaker''s name?', NULL, 'beginner', 'The speaker said "My name is Tom."', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', 'Hello! My name is Tom.'),
	('bc567bac-1fb5-4244-a05b-cc1f050dfa8e', 'multiple_choice', 'What do you call your father''s or mother''s daughter (not you)?', NULL, 'beginner', 'That person is your "sister".', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
	('41dd9ed6-7b74-4e1c-806a-7072cef7431d', 'fill_in_the_blank', 'Complete: "This is my ___." (a word for a male parent)', NULL, 'beginner', '"Father" is a male parent.', NULL, '{}', 'published', '00000000-0000-0000-0000-000000000001', '2026-07-07 09:55:01.507197+00', '2026-07-07 09:55:01.507197+00', NULL),
