	('67b806ef-1026-5290-b469-62a106604023', 'multiple_choice', 'She _____ from Spain.', NULL, 'beginner', 'Use "is" with he, she and it.', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('00a2e91d-6cae-53b0-b5d4-d6e99db8b453', 'multiple_choice', 'Which sentence is correct?', NULL, 'beginner', '"We" goes with "are".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('d574c87b-bf35-5def-9a98-5decd545320e', 'multiple_choice', 'Which sentence uses "to be" correctly?', NULL, 'beginner', 'Use "are" with "they".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('f06eb214-3036-5f2c-b37a-2c1bf83742cc', 'true_false', '"He are my brother" is a correct sentence.', NULL, 'beginner', '"He" needs "is": "He is my brother."', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('41366551-dbf6-5243-b331-ac699a1618b5', 'true_false', '"I am Ana" is a correct sentence.', NULL, 'beginner', '"I" goes with "am".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('c37dd485-d426-57b3-a797-466e11f5f888', 'fill_in_the_blank', 'It _____ a pen. (to be)', NULL, 'beginner', '"It" goes with "is".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('1767d29f-d558-542d-9eb6-ef56dc050b0c', 'fill_in_the_blank', 'My friends _____ in the park. (to be)', NULL, 'beginner', '"Friends" is plural, so use "are".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('2a1472d3-154a-5c33-8877-d5e642801e9b', 'fill_in_the_blank', 'I _____ ready. (to be)', NULL, 'beginner', 'Use "am" with "I".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9f219978-8a86-5562-bcb3-29c579e36a28', 'multiple_choice', 'What is a good way to say your name?', NULL, 'beginner', 'The correct pattern is "My name is ...".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('dd74017d-ccc1-54e3-943b-7ccc9199c332', 'multiple_choice', 'Which sentence tells where you are from?', NULL, 'beginner', 'Use "I am from + country".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
