	('003d7dd1-f00b-5ab8-aee9-0e1b31a0db80', 'multiple_choice', 'Which greeting is best in the morning?', NULL, 'beginner', '"Good morning" is used before noon.', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('22762399-2c3d-5f0f-b426-0b4145981a16', 'multiple_choice', 'Which sentence is correct?', NULL, 'beginner', '"She" goes with "is".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('181a7443-1bfb-53ba-b1e7-ad0ba1c0bc9d', 'true_false', '"Good night" is a greeting for the morning.', NULL, 'beginner', '"Good night" is said at the end of the day.', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
