	('607821ba-f10b-594c-b296-c97ecefbdd51', 'fill_in_the_blank', 'Hello, my name _____ Maria. (to be)', NULL, 'beginner', '"Name" is singular, so use "is".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('ce3de67b-7334-5aa0-92f7-ad8e368d572e', 'fill_in_the_blank', 'I am _____ Egypt. (from / at)', NULL, 'beginner', 'We say "I am from + country".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('5649b1bd-271c-5290-aad1-e581493a3b6a', 'fill_in_the_blank', 'Nice to _____ you. (meet / see)', NULL, 'beginner', 'The phrase is "Nice to meet you".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('4bc65771-3b18-5a58-9897-3d9479c09075', 'multiple_choice', 'Ali says: "Hi, I am Ali. What is your name?" What is the best answer?', NULL, 'beginner', 'The question asks for a name.', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('28c85994-8a5d-51b5-8a4c-dd993f8b4a0a', 'multiple_choice', 'Lina says "Nice to meet you." What is a good reply?', NULL, 'beginner', 'We answer "Nice to meet you" with "Nice to meet you too".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('a2c1e569-6c31-5af1-9903-5047edf55ea6', 'multiple_choice', '"Are you a new student?" Which answer is correct?', NULL, 'beginner', 'The short answer uses "I am".', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('a4973261-cb43-5cf5-a03d-47dc94d01f14', 'multiple_choice', 'Which question asks for a name?', NULL, 'beginner', '"What is your name?" asks for a name.', NULL, '{lesson-practice,a1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
