	('7129c089-089f-5514-a97d-5a896c962394', 'multiple_choice', 'Which two days make the weekend?', NULL, 'beginner', 'Saturday and Sunday are the weekend.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9f9fd2a2-0fe0-584f-a729-11c1cfdc35ec', 'multiple_choice', 'Which sentence is correct?', NULL, 'beginner', 'Use "on" with days.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('517003bc-f972-5b59-9f7e-6f372bfb6f21', 'multiple_choice', 'How many days are in a week?', NULL, 'beginner', 'There are seven days in a week.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('84f8bf18-974c-5a91-b364-0f4358dd0053', 'true_false', 'Wednesday comes before Tuesday.', NULL, 'beginner', 'Tuesday comes before Wednesday.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9aa349c6-2c82-52a6-ab0b-a942dab95c39', 'true_false', 'We use "on" before days of the week.', NULL, 'beginner', 'Example: on Friday.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('c6ee2670-c54b-5a9c-8aa7-b535d9aaebe2', 'fill_in_the_blank', 'The first day of the school week is _____.', NULL, 'beginner', 'Most school weeks start on Monday.', NULL, '{lesson-practice,a1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
