	('b0eda7d8-3903-5dfc-9a98-512b065a2f91', 'multiple_choice', 'They _____ football on Saturday.', NULL, 'elementary', 'Regular past: play + ed.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('b4c30e5b-55b5-5fd5-81be-18875c38836e', 'multiple_choice', 'What is the past simple of "study"?', NULL, 'elementary', 'Consonant + y changes to -ied.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('1bbbc041-1b60-56fb-8449-4e3c63a7db3b', 'multiple_choice', 'What is the past simple of "stop"?', NULL, 'elementary', 'One-syllable verbs with a short vowel double the final consonant.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('ea1d399c-5051-5537-8419-3db28ab2932b', 'true_false', 'The past simple of regular verbs ends in -ed.', NULL, 'elementary', 'Example: work → worked.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('7522c277-0435-56a8-a845-dbe66abc6201', 'true_false', '"He walk to school yesterday" is correct.', NULL, 'elementary', 'Say "He walked to school yesterday."', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('58672b67-cb88-58b0-b02b-068e47a7e440', 'fill_in_the_blank', 'We _____ TV last night. (watch)', NULL, 'elementary', 'Add -ed: watched.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('39657250-a094-5fcb-894a-5fc27083ef4c', 'fill_in_the_blank', 'My mother _____ dinner yesterday. (cook)', NULL, 'elementary', 'Add -ed: cooked.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('de5f1e48-5f4d-5d0e-98ae-d7769b33bb0a', 'fill_in_the_blank', 'I _____ English at school last year. (study)', NULL, 'elementary', 'Consonant + y → -ied.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('cc5d789c-4024-5a55-8f91-ea700a777dee', 'multiple_choice', 'What is the past simple of "go"?', NULL, 'elementary', '"Go" is irregular: go → went.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('bae3d103-8e9a-5dbb-b0c5-36bc1a1a1d74', 'multiple_choice', 'What is the past simple of "see"?', NULL, 'elementary', '"See" is irregular: see → saw.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('26f45a72-e047-52e0-8248-ea9082251f7b', 'multiple_choice', 'What is the past simple of "eat"?', NULL, 'elementary', '"Eat" is irregular: eat → ate.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9ffdbe1e-e2d3-5b94-828e-1c0f23c39d78', 'multiple_choice', 'What is the past simple of "have"?', NULL, 'elementary', '"Have" is irregular: have → had.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('fc0ac5ac-cf4a-5878-9f0a-dd392ffb1b45', 'multiple_choice', 'Which sentence is correct?', NULL, 'elementary', 'Use the irregular past "went".', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('ea57738e-3d8f-5b4e-9736-e09078e70f09', 'true_false', '"Buyed" is the past simple of "buy".', NULL, 'elementary', 'The past of "buy" is "bought".', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('92eb70f7-8dc0-5fb2-a720-56f0d85cb393', 'true_false', '"Ate" is the past simple of "eat".', NULL, 'elementary', 'Eat → ate.', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('4891af47-426e-5de5-9b49-27c86631fc82', 'fill_in_the_blank', 'Last week she _____ a beautiful bird. (see)', NULL, 'elementary', 'The past of "see" is "saw".', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('18ba1a94-fc5a-503a-9a5d-998b7bebb52f', 'fill_in_the_blank', 'We _____ pizza for dinner yesterday. (have)', NULL, 'elementary', 'The past of "have" is "had".', NULL, '{lesson-practice,a2.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
