	('887bd1fa-cb57-5ee8-bc2f-7a5666279504', 'multiple_choice', 'The man _____ lives next door is a doctor.', NULL, 'intermediate', '"Who" is for people.', NULL, '{lesson-practice,b1+}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('fede6e20-eb19-5429-a7fc-78f32d459775', 'multiple_choice', 'The book _____ I bought is interesting.', NULL, 'intermediate', '"That" refers to things.', NULL, '{lesson-practice,b1+}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('2eba2e03-b10f-580a-8705-6ee2ecc1a6e1', 'multiple_choice', 'The car _____ is parked outside is mine.', NULL, 'intermediate', '"Which" refers to things.', NULL, '{lesson-practice,b1+}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
