	('d51f175a-da73-5536-bd5c-ca7f0cf93b9a', 'multiple_choice', '_____ you ever been to London?', NULL, 'intermediate', 'Present perfect questions use "Have you ever + past participle".', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('e19bea81-8253-5a83-bd98-b71f4175a5f2', 'multiple_choice', 'I have never _____ sushi.', NULL, 'intermediate', 'Present perfect: have + past participle (eaten).', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('408d2326-d43f-5b02-a735-61775627dc40', 'multiple_choice', 'She has _____ to Italy three times.', NULL, 'intermediate', '"Has been to" talks about experience.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('50af0901-28bf-5631-bece-1fba58456ee8', 'multiple_choice', 'Which sentence talks about life experience?', NULL, 'intermediate', 'The present perfect with no time word expresses experience.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('067f3247-edd0-5769-a8cc-d69eac06666e', 'multiple_choice', 'What is the past participle of "see"?', NULL, 'intermediate', 'See – saw – seen.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('cd940f03-7ae2-57e2-8f0f-72911ca4517a', 'true_false', 'We use the present perfect to talk about experiences up to now.', NULL, 'intermediate', 'Example: "I have lived in three cities."', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('d71fa132-f689-5743-85e6-5ad39a837bd8', 'true_false', '"Have you ever went to Paris?" is correct.', NULL, 'intermediate', 'Use the past participle: "Have you ever been to Paris?"', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
