	('121e4f6a-4dea-5347-9602-284cfd511234', 'multiple_choice', 'I _____ to Spain last summer.', NULL, 'intermediate', '"Last summer" is a finished time: past simple.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('dee1e068-e76d-5084-be20-db22b338fbb7', 'multiple_choice', 'I _____ Paris three times in my life.', NULL, 'intermediate', 'No specific time: present perfect.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
