	('f324b0a7-a2ad-5df8-afa4-ed0da2008109', 'multiple_choice', '"If the weather is good, we''ll have a picnic." What is the condition?', NULL, 'intermediate', 'The if clause is the condition.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('fd8e5d96-9540-5835-a90d-6732580755a4', 'multiple_choice', 'Which sentence is correct for a plan that depends on time?', NULL, 'intermediate', 'If + present, will + verb.', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('40797bc5-3696-564c-8770-6d541951d465', 'multiple_choice', 'Which word can replace "if not" in a first conditional?', NULL, 'intermediate', '"Unless" means "if not".', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('345b95d9-e197-5914-a64a-b65b2903f2fe', 'multiple_choice', '"I won''t go unless you come." means:', NULL, 'intermediate', '"Unless" = "if not".', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('7495a07b-96f0-51d3-a6d8-977ee8132a8b', 'true_false', '"Unless" means "if not".', NULL, 'intermediate', 'Example: "Unless you hurry = If you don''t hurry".', NULL, '{lesson-practice,b1.1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
