	('ce87620c-95b0-567a-ba3f-4ac2968a25ac', 'multiple_choice', '"You should take a break every hour." This is:', NULL, 'intermediate', '"Should" gives advice.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('c9e55a32-2751-5cf4-98da-1bbcf139a5c1', 'multiple_choice', 'Which sentence is a workplace rule?', NULL, 'intermediate', '"Must" is a rule.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('543892a5-e2ee-556f-a185-0592eae56bb5', 'multiple_choice', 'Which sentence is workplace advice?', NULL, 'intermediate', '"Should" is advice.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('c263188a-6d40-57b8-b234-0105fe26fed6', 'multiple_choice', 'Which sentence expresses something not necessary?', NULL, 'intermediate', '"Don''t have to" = not required.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('727a9275-a0ca-5394-8a23-f6485d7e518e', 'true_false', '"Must" is stronger than "should".', NULL, 'intermediate', 'Must = obligation, should = advice.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
