	('f7398535-13c9-5ae4-bc9d-1cb935a2ffa9', 'fill_in_the_blank', 'You _____ bring your lunch; there''s a canteen.', NULL, 'intermediate', 'Not necessary.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9d421e03-d1f0-58de-9011-cbba8d4c3a61', 'multiple_choice', 'Which phrase introduces an opinion?', NULL, 'intermediate', '"In my opinion" is used for opinions.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('641cdb4b-8e31-5990-945c-c348af189120', 'multiple_choice', 'Which phrase is NOT an opinion phrase?', NULL, 'intermediate', '"It is a fact that" introduces facts.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('c60c5302-b15e-5d59-9ebd-1df4fe4f81b4', 'multiple_choice', 'Which sentence expresses an opinion?', NULL, 'intermediate', '"I believe" = opinion.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('87e2f466-f1e2-58df-a62b-98627a1c9d09', 'multiple_choice', 'Which sentence is correct?', NULL, 'intermediate', 'Correct grammar.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9ae48488-3ce1-5956-b432-59a9a7ed9408', 'multiple_choice', 'Which phrase can start a polite opinion?', NULL, 'intermediate', '"From my point of view" is neutral and polite.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('5b361e59-870e-5b2f-94de-d1bc659caf30', 'true_false', '"I believe" and "I think" are common ways to give an opinion.', NULL, 'intermediate', 'They are standard phrases.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('56090bb6-81a8-57f0-8efa-f870af027ad5', 'true_false', 'Opinions are always facts.', NULL, 'intermediate', 'Opinions are personal views.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9f827385-f833-5f2c-b0d7-990eb21ce6b8', 'fill_in_the_blank', '_____ my opinion, homework should be shorter.', NULL, 'intermediate', '"In my opinion".', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
