	('a17b56f1-78af-590d-a4bc-f3cf93854f02', 'fill_in_the_blank', 'From my point of _____ , the city is too noisy.', NULL, 'intermediate', '"From my point of view".', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('821cd842-b887-5593-b66c-632e485e08c4', 'multiple_choice', 'A: "I think cats are better than dogs." B: "I agree." What does B mean?', NULL, 'intermediate', '"I agree" = same opinion.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('109bbb53-6ae4-5321-8401-0aa1de851ec3', 'multiple_choice', 'Which phrase expresses polite disagreement?', NULL, 'intermediate', 'It is soft and polite.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('ba1c0994-4418-58f9-88bd-d1d23e9b6d6f', 'multiple_choice', 'Which phrase agrees strongly?', NULL, 'intermediate', '"Completely agree" is strong agreement.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('d634b92d-8b5b-57c8-b90a-45256714aa51', 'multiple_choice', 'Which phrase is another way to say "I disagree" politely?', NULL, 'intermediate', 'It''s polite.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('bda51cc8-a402-5a57-934e-7525fb256307', 'multiple_choice', 'Which response agrees with "It''s a beautiful day"?', NULL, 'intermediate', '"That''s true" agrees.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('9a1224a1-3221-5a31-8498-84c723a53879', 'true_false', '"I see it differently" is a polite way to disagree.', NULL, 'intermediate', 'It softens the disagreement.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
