	('2ae6abe3-e977-5b5f-b268-a8cd5e0ebaed', 'multiple_choice', 'Ana: "I think students should wear uniforms. It makes everyone equal." Ben: "I don''t agree. Uniforms stop people from expressing themselves." Who is for uniforms?', NULL, 'intermediate', 'Ana thinks students should wear uniforms.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('7abc39ec-e0fd-56a3-9291-4f78c9a45710', 'multiple_choice', 'Ana: "I think students should wear uniforms. It makes everyone equal." Ben: "I don''t agree. Uniforms stop people from expressing themselves." Why does Ben disagree?', NULL, 'intermediate', 'Ben says uniforms stop people from expressing themselves.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('44b829ea-dea4-5969-8277-c44d06a51c3a', 'multiple_choice', 'Ana says uniforms make everyone equal. This is her:', NULL, 'intermediate', 'It supports her opinion.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
