	('9331b816-d43f-517f-b7d9-94624ff722ca', 'true_false', 'In the debate, Ana and Ben have different opinions.', NULL, 'intermediate', 'One agrees, the other disagrees.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('5e736904-dd5a-5e5e-b63b-64b16a622c87', 'true_false', 'Ben agrees that uniforms make everyone equal.', NULL, 'intermediate', 'He disagrees.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
