	('316fad4f-524f-559f-8dba-dd34f1e36f70', 'fill_in_the_blank', 'Ben: I''m sorry, but I _____ agree.', NULL, 'intermediate', 'Disagreement.', NULL, '{lesson-practice,b1.2}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
