	('aaa78236-23be-5a28-a422-04a82646767d', 'multiple_choice', 'Which sentence correctly joins two ideas that are both true?', NULL, 'beginner', '"And" adds a similar idea.', NULL, '{lesson-practice,w1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('1dcb89a1-74cb-5948-be3b-971486ff7aa3', 'multiple_choice', 'Which sentence shows a contrast?', NULL, 'beginner', '"But" shows contrast.', NULL, '{lesson-practice,w1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('234590c6-7903-52e0-833e-497afd4bdf01', 'multiple_choice', 'Which word joins two similar ideas?', NULL, 'beginner', '"And" joins similar ideas.', NULL, '{lesson-practice,w1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
	('56949e8c-5962-5846-a26e-7a7ba15843ce', 'multiple_choice', 'Which word shows two different ideas?', NULL, 'beginner', '"But" shows contrast.', NULL, '{lesson-practice,w1}', 'published', '00000000-0000-0000-0000-000000000001', '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00', NULL),
