	('debfcdb4-bd93-414e-96c5-44f25d67a36b', 'en.a2.voc.restaurants', 'Food & Restaurants', 'Ordering food at a restaurant, menus, and restaurant etiquette.', 'vocabulary', NULL, 'published', '2026-07-07 10:19:46.521121+00', '2026-07-07 10:19:46.521121+00'),
	('357dfb3f-a1dc-438a-8e6c-cd5f6644cfa7', 'en.b1.voc.personality', 'Personality Adjectives', 'Describing personality traits (friendly, honest, generous, stubborn, patient).', 'vocabulary', NULL, 'published', '2026-07-07 10:25:06.813259+00', '2026-07-07 10:25:06.813259+00'),
	('505b3d4f-96f6-49d5-ad17-0e4c1259512d', 'en.b1.gra.past_continuous', 'Narrative Past (Past Continuous + Past Simple)', 'Combining past continuous (background action) with past simple (interrupting event) to tell stories.', 'grammar', NULL, 'published', '2026-07-07 10:27:30.862497+00', '2026-07-07 10:27:30.862497+00'),
	('f56f0c09-8c7d-4958-8571-1b3fa51f0d02', 'en.b1.voc.travel_culture', 'Travel & Culture', 'Vocabulary for traveling abroad, customs, and cultural differences.', 'vocabulary', NULL, 'published', '2026-07-07 10:27:30.862497+00', '2026-07-07 10:27:30.862497+00'),
	('27cea36c-ac6b-4e36-a860-d660f9e317b6', 'en.b1.gra.modals_obligation', 'Modal Verbs of Obligation', 'Using must, have to, and should to express obligation and advice.', 'grammar', NULL, 'published', '2026-07-07 10:27:30.862497+00', '2026-07-07 10:27:30.862497+00'),
	('ed951a1e-9af7-4379-bef3-309b35c8bde2', 'en.b1.func.agree_disagree', 'Agreeing & Disagreeing', 'Phrases for politely agreeing and disagreeing with opinions.', 'functional_language', NULL, 'published', '2026-07-07 10:27:30.862497+00', '2026-07-07 10:27:30.862497+00'),
	('4c7ea220-2fb2-4620-8a13-dd677e919cf6', 'en.b1.gra.zero_conditional', 'Zero Conditional', 'Using zero conditional (If + present, present) for facts and general truths.', 'grammar', NULL, 'published', '2026-07-07 10:30:02.39399+00', '2026-07-07 10:30:02.39399+00'),
	('c19c5fb4-1d39-4d33-91ec-55aca1afa1fe', 'en.b1.gra.reported_speech_statements', 'Reported Speech: Statements', 'Reporting what someone said using backshifted statements ("She said that...").', 'grammar', NULL, 'published', '2026-07-07 10:30:02.39399+00', '2026-07-07 10:30:02.39399+00'),
	('677c9f5b-6ae5-40f9-9287-db7b4d320e67', 'en.b1.voc.phrasal_verbs_common', 'Common Phrasal Verbs', 'Everyday phrasal verbs (give up, look for, turn off, find out).', 'vocabulary', NULL, 'published', '2026-07-07 10:30:02.39399+00', '2026-07-07 10:30:02.39399+00'),
	('9127c8f9-9c08-4fe0-b769-bf142dff65e8', 'en.b1.spe.structured_speaking', 'Structured Speaking: Giving Extended Answers', 'Giving structured, multi-sentence spoken answers to discussion questions (point + reason + example).', 'speaking', NULL, 'published', '2026-07-07 10:30:02.39399+00', '2026-07-07 10:30:02.39399+00'),
	('b5c8a6d1-83b4-4e77-b62d-19f785a4c036', 'en.b2.gra.discourse_markers', 'Advanced Connectors & Discourse Markers', 'Using connectors like however, moreover, in addition, and therefore to link ideas.', 'grammar', NULL, 'published', '2026-07-07 11:08:59.06535+00', '2026-07-07 11:08:59.06535+00'),
	('d80d7284-98eb-4ab1-8f9e-0041b36939d3', 'en.b2.gra.preferences_hypotheticals', 'Expressing Preferences & Hypotheticals', 'Using "would rather", "would prefer", and "I wish" to express preferences and hypothetical wishes.', 'grammar', NULL, 'published', '2026-07-07 11:08:59.06535+00', '2026-07-07 11:08:59.06535+00'),
	('14eb2ef3-506d-41f4-88fd-54fd5c402afb', 'en.w2.write.paragraph_structure', 'Paragraph Structure & Topic Sentences', 'Organizing a paragraph around a clear topic sentence with supporting details.', 'writing', NULL, 'published', '2026-07-07 11:11:24.621894+00', '2026-07-07 11:11:24.621894+00'),
	('e3329546-10f5-4fca-a9dd-79a3ddd61a68', 'en.w2.write.register', 'Formal vs Informal Register', 'Choosing appropriately formal or informal language for the audience and purpose.', 'writing', NULL, 'published', '2026-07-07 11:11:24.621894+00', '2026-07-07 11:11:24.621894+00'),
	('f03e3daa-0d6e-4630-b92f-ebf6bbe18667', 'en.w2.write.opinion_essay', 'Opinion Essays (Basic Structure)', 'Writing a short opinion essay with an introduction, supporting paragraphs, and conclusion.', 'writing', NULL, 'published', '2026-07-07 11:11:24.621894+00', '2026-07-07 11:11:24.621894+00'),
	('36be488b-400d-42ca-8228-6190f2afa578', 'en.w2.write.emails_requests', 'Emails & Requests', 'Writing clear emails, including polite requests, in an appropriate register.', 'writing', NULL, 'published', '2026-07-07 11:11:24.621894+00', '2026-07-07 11:11:24.621894+00'),
	('742b5a8f-4f8c-4510-a484-f17df92d86bd', 'en.w2.write.cohesion_linking', 'Linking Words for Cohesion', 'Using linking words and phrases to connect ideas smoothly across a paragraph.', 'writing', NULL, 'published', '2026-07-07 11:11:24.621894+00', '2026-07-07 11:11:24.621894+00'),
	('735c283b-c328-4d3a-bfa5-263e5121e0bf', 'en.b2.gra.third_conditional', 'Third Conditional', 'Using third conditional (If + past perfect, would have + past participle) to talk about unreal past situations.', 'grammar', NULL, 'published', '2026-07-07 11:14:56.279163+00', '2026-07-07 11:14:56.279163+00'),
	('dcb4918d-b1ed-4217-9df6-878427723491', 'en.b2.gra.reported_speech_questions_commands', 'Reported Speech: Questions & Commands', 'Reporting yes/no and wh- questions, and commands, with correct word order and backshift.', 'grammar', NULL, 'published', '2026-07-07 11:14:56.279163+00', '2026-07-07 11:14:56.279163+00'),
	('c4636a30-95f0-489a-a160-986deb3a7f4f', 'en.b2.gra.modals_deduction', 'Modal Verbs of Deduction', 'Using must/might/could/can''t to make logical deductions about present and past situations.', 'grammar', NULL, 'published', '2026-07-07 11:14:56.279163+00', '2026-07-07 11:14:56.279163+00'),
	('27dd54e0-8ab3-49c2-a499-370eaa5a0b92', 'en.b2.gra.relative_clauses_nondefining', 'Relative Clauses (Non-Defining)', 'Adding extra, non-essential information with commas using non-defining relative clauses.', 'grammar', NULL, 'published', '2026-07-07 11:14:56.279163+00', '2026-07-07 11:14:56.279163+00'),
