INSERT INTO public.skills (id, key, title, description, domain, parent_skill_id, status, created_at, updated_at) VALUES
	('6c827e8c-cc70-4bc8-86a7-e2be1837c153', 'en.b2.voc.phrasal_verbs_advanced', 'Advanced Phrasal Verbs in Context', 'Less literal, more idiomatic phrasal verbs (come across, go through, look into, put up with).', 'vocabulary', NULL, 'published', '2026-07-07 11:27:52.805484+00', '2026-07-07 11:27:52.805484+00'),
	('f1ebda6f-0282-4041-a382-39ba984aa1a3', 'en.b2.gra.modality_nuance', 'Nuance in Modality', 'Subtle differences in strength and meaning between related modal verbs (should/ought to, may/might, can/could).', 'grammar', NULL, 'published', '2026-07-07 11:27:52.805484+00', '2026-07-07 11:27:52.805484+00'),
	('00fe138a-8490-47bd-a044-c22084dafae9', 'en.b2.spe.debating_opinions', 'Debating Opinions', 'Structuring a spoken argument, responding to counterpoints, and debating an opinion respectfully.', 'speaking', NULL, 'published', '2026-07-07 11:27:52.805484+00', '2026-07-07 11:27:52.805484+00'),
	('d863cef1-a64e-4672-9648-1a9150ac1139', 'en.c1.gra.inversion_emphasis', 'Inversion & Emphatic Structures', 'Using inversion (Never have I..., Not only did...) and emphatic do for literary/formal emphasis.', 'grammar', NULL, 'published', '2026-07-07 12:19:52.307733+00', '2026-07-07 12:19:52.307733+00'),
	('ecb88e1d-3943-4012-91aa-7b0467dbce38', 'en.c1.voc.idioms_collocations', 'Advanced Idioms & Collocations', 'Understanding and using sophisticated idioms and natural word collocations.', 'vocabulary', NULL, 'published', '2026-07-07 12:19:52.307733+00', '2026-07-07 12:19:52.307733+00'),
	('c1377fbd-3484-4901-99bb-98ba3943c140', 'en.c1.func.academic_register', 'Academic & Formal Register', 'Using precise, impersonal, and hedged language appropriate to academic and formal contexts.', 'functional_language', NULL, 'published', '2026-07-07 12:19:52.307733+00', '2026-07-07 12:19:52.307733+00'),
	('30a8d552-4e0f-4d74-bad6-a62123ee4e80', 'en.c1.gra.complex_conditionals', 'Complex Conditionals', 'Combining conditional structures with inversion (Were I to..., Had it not been for...) for formal or literary effect.', 'grammar', NULL, 'published', '2026-07-07 12:19:52.307733+00', '2026-07-07 12:19:52.307733+00'),
	('cc22a100-646d-47b8-89e9-2e670aef3026', 'en.c1.func.hedging_nuanced', 'Nuanced Hedging & Softening Language', 'Fine-grained hedging and softening devices (it could be argued, to a certain extent, seemingly) for diplomatic, precise communication.', 'functional_language', NULL, 'published', '2026-07-07 12:22:14.738737+00', '2026-07-07 12:22:14.738737+00'),
	('aaca51e6-0228-4175-abe2-8984afe42f36', 'en.c1.write.cohesion_extended', 'Cohesion in Extended Discourse', 'Maintaining cohesion across multiple paragraphs using reference, substitution, and varied linking devices.', 'writing', NULL, 'published', '2026-07-07 12:22:14.738737+00', '2026-07-07 12:22:14.738737+00'),
	('d93f7c18-ae18-4a93-ab3f-576e8486c474', 'en.c1.spe.persuasive_argumentative', 'Persuasive & Argumentative Speaking', 'Building a persuasive spoken argument with rhetorical techniques and rebutting opposing views.', 'speaking', NULL, 'published', '2026-07-07 12:22:14.738737+00', '2026-07-07 12:22:14.738737+00'),
	('00d65d2d-e267-404d-ac8a-e317c3671765', 'en.w3.write.argumentative_essay', 'Argumentative Essays', 'Writing a full argumentative essay with a thesis, counterargument, rebuttal, and conclusion.', 'writing', NULL, 'published', '2026-07-07 12:24:56.398776+00', '2026-07-07 12:24:56.398776+00'),
	('b81c5219-d7a7-42e5-af5a-9ddb77d0677a', 'en.w3.write.synthesizing_viewpoints', 'Synthesizing Multiple Viewpoints', 'Integrating and comparing multiple perspectives on an issue into a coherent piece of writing.', 'writing', NULL, 'published', '2026-07-07 12:24:56.398776+00', '2026-07-07 12:24:56.398776+00'),
	('bea74c99-8b6d-4781-9d47-3f81b8e7812f', 'en.w3.write.editing_cohesion_conciseness', 'Editing for Cohesion & Conciseness', 'Revising a draft to tighten wordy sentences and strengthen cohesion between ideas.', 'writing', NULL, 'published', '2026-07-07 12:24:56.398776+00', '2026-07-07 12:24:56.398776+00'),
	('6e6261a1-ab3b-4d11-95aa-f075e87357cd', 'en.c2.func.idiom_register_control', 'Native-Level Idiom & Register Control', 'Fluidly shifting idiom and register across social, professional, and formal contexts like a native speaker.', 'functional_language', NULL, 'published', '2026-07-07 17:21:37.890573+00', '2026-07-07 17:21:37.890573+00'),
