	('2b88e0b5-1181-4097-8b88-95d960cae658', '3f3971ed-f207-45af-bdd0-0e3736ac694d', 'en', 'The Alphabet A-Z', 'Learn to recognize and say every letter of the English alphabet.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('cc87ae91-a85e-42a0-907a-616af831463e', '1fead9f5-0622-4340-b535-1c058c524373', 'en', 'Short Vowel Sounds', 'Practice the five short vowel sounds: a, e, i, o, u.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('82089b95-770c-4da4-893d-02100709ea76', '91ed04f5-2451-4a5e-ba87-8019a26cf5db', 'en', 'Consonant Pairs & Blends', 'Listen to and practice tricky consonant sounds like p/b, f/v, and blends like "bl", "st".', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('4a943193-6351-45c5-8bd7-1b809ddd11f2', 'c22f5f45-e427-4cc4-bc40-270ce97f27c1', 'en', 'Numbers 0-10', 'Learn to say and recognize numbers 0 through 10.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('35e1acff-4f89-4f8d-877d-b3078528efc4', '8e45a282-d726-48ef-97c5-897764156bb9', 'en', 'Numbers 11-20', 'Learn to say and recognize numbers 11 through 20.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('9b24f2b7-ca5a-4b63-ac0e-b1af70c67b8d', 'ec07a074-825b-4d4d-91b6-c612b7a58df6', 'en', 'Counting Practice', 'Listen to spoken numbers and practice recognizing them by ear.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
	('3afe00f8-b3a2-4a10-9aee-850fcb01bca1', '45256e4f-559f-4d32-8652-53d61dc2e241', 'en', 'Hello & Goodbye', 'Learn the most common greetings and farewells.', '2026-11-01 17:29:57.005456+00', '2026-11-01 17:29:57.005456+00'),
