INSERT INTO public.lesson_translations (id, lesson_id, locale, title, description, created_at, updated_at) VALUES
	('403a4bb0-e976-4b51-8896-df740c47c1c0', 'ebd2391c-8264-42d8-9444-caad095b877b', 'ar', 'You Should Study More', 'استخدم "should" لتقديم النصيحة.', '2026-11-01 17:30:08.110989+00', '2026-11-01 17:30:08.110989+00'),
