INSERT INTO public.lesson_translations (id, lesson_id, locale, title, description, created_at, updated_at) VALUES
	('fe4f560b-fc4d-4680-9caa-e846f027bb51', 'f9166db6-eade-4799-b718-681983667083', 'ar', 'حلقة نقاش طويلة', 'تابع حلقة نقاش ممتدة بين عدة متحدثين وتداخل وجهات النظر.', '2026-11-01 17:30:08.110989+00', '2026-11-01 17:30:08.110989+00'),
	('8eb98838-597a-4040-92d9-77cba7a70752', 'fd200267-ed5f-4022-b46e-391b862bc12d', 'ar', 'المحدِّدة مقابل غير المحدِّدة', 'ميّز بين جمل الصلة المحدِّدة (الأساسية) وغير المحدِّدة (الإضافية).', '2026-11-01 17:30:08.110989+00', '2026-11-01 17:30:08.110989+00'),
