INSERT INTO public.practice_topics (id, kind, level_code, xp_reward, time_limit_seconds, min_words, ai_prompt, sort_order, is_active, created_at, updated_at) VALUES
	('e0000000-0000-0000-0000-000000000101', 'speaking', 'A1', 20, 180, NULL, 'You are Sam, a friendly friend of the student. The two of you are chatting about weekend plans. Start by asking what they want to do this weekend. React to what they say, ask one short follow-up question at a time, and share one small thing about your own plans.', 1, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000102', 'speaking', 'A2', 30, 240, NULL, 'You are Mr. Brown, the student''s boss at a small company. The student is your employee and wants to ask you for one day off next week. Be polite but realistic: ask why, when, and who will cover their work. Stay in role as the boss; keep each turn to one or two short sentences.', 2, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000103', 'speaking', 'A2', 30, 240, NULL, 'You are Alex, a friendly classmate the student has just met at a community class. The two of you are planning a fun, respectful day out together as friends: where to go, what time, what to eat. Keep the tone light and polite, ask one short question at a time, and stay in role.', 3, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000104', 'speaking', 'A1', 20, 180, NULL, 'You are a waiter at a small restaurant and the student is the customer. Greet them, offer a simple menu (soup, chicken, pasta, salad, tea, juice), take their order, and ask if they want anything else. Keep turns very short and speak simply.', 4, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000105', 'speaking', 'A2', 30, 240, NULL, 'You are Dr. Lee, a kind doctor. The student is your patient and does not feel well. Ask what is wrong, how long it has lasted, and give simple, safe advice (rest, water, see a pharmacist). Do not give diagnoses or name medicines. Keep turns short and simple.', 5, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000106', 'speaking', 'A1', 20, 180, NULL, 'You are a shop assistant in a clothes shop and the student is a customer who wants to buy a shirt. Ask about size, colour and budget, suggest one or two items, and talk about the price. Keep turns very short and speak simply.', 6, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000201', 'writing', 'A1', 20, 600, 30, 'The student describes their daily routine from morning to night.', 1, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000202', 'writing', 'A1', 20, 600, 30, 'The student describes their best friend: appearance, personality and what they do together.', 2, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000203', 'writing', 'A1', 20, 600, 30, 'The student describes their family members and what each one does.', 3, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000204', 'writing', 'A2', 30, 900, 50, 'The student writes about their favourite food: what it is, how it tastes, and when they eat it.', 4, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000205', 'writing', 'A2', 30, 900, 50, 'The student tells about a trip they took, using the past tense: where, with whom, what they did.', 5, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e0000000-0000-0000-0000-000000000206', 'writing', 'A2', 30, 900, 50, 'The student writes about their dream job: what it is, why they want it and what they need to learn.', 6, true, '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00');
INSERT INTO public.practice_topic_translations (id, topic_id, locale, title, description, created_at, updated_at) VALUES
	('4cec2d14-e343-45e1-af2d-ef7ce78670e8', 'e0000000-0000-0000-0000-000000000101', 'en', 'Chat with a friend: weekend plans', 'Talk to a friend about what you will do this weekend.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('1a62d775-5976-443e-9508-18c2a5def444', 'e0000000-0000-0000-0000-000000000101', 'ar', 'محادثة مع صديق: خطط نهاية الأسبوع', 'تحدّث مع صديقك عمّا ستفعله في نهاية هذا الأسبوع.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('add0f415-47d2-4168-954a-2825d01653d1', 'e0000000-0000-0000-0000-000000000102', 'en', 'Employee and boss: asking for a day off', 'You are an employee. Ask your boss politely for a day off.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('dde3c0d7-a6b5-4708-a8c4-1d77f9f8a1d2', 'e0000000-0000-0000-0000-000000000102', 'ar', 'موظف ومديره: طلب إجازة ليوم', 'أنت موظف. اطلب من مديرك بأدب إجازة ليوم واحد.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('ff7087c0-0cc7-4620-a2a4-2dbca8798fc1', 'e0000000-0000-0000-0000-000000000103', 'en', 'Two friends planning a day out', 'A boy and a girl who are friends plan a day out together.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('8fe6090e-8f49-45d2-8238-429fc3bd46e6', 'e0000000-0000-0000-0000-000000000103', 'ar', 'صديقان يخططان ليوم خارج المنزل', 'شاب وفتاة صديقان يخططان لقضاء يوم معًا.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('247879ca-e5f2-4613-8d5c-b7d8181cbca4', 'e0000000-0000-0000-0000-000000000104', 'en', 'At a restaurant', 'Order food and drinks from a waiter.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('b492e644-a2a7-4dee-a54e-3c5c535cfb90', 'e0000000-0000-0000-0000-000000000104', 'ar', 'في المطعم', 'اطلب الطعام والمشروبات من النادل.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('1fd41717-841f-4eba-b759-18541496e5ea', 'e0000000-0000-0000-0000-000000000105', 'en', 'At the doctor', 'Tell the doctor how you feel and listen to simple advice.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('d9ed35b9-8d05-46f7-ade3-a9983672bbe3', 'e0000000-0000-0000-0000-000000000105', 'ar', 'عند الطبيب', 'أخبر الطبيب كيف تشعر واستمع إلى نصيحة بسيطة.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('d418c934-b6ad-4216-a057-90574a36aa8a', 'e0000000-0000-0000-0000-000000000106', 'en', 'Shopping for clothes', 'Buy a shirt: talk about size, colour and price.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('d72cbbb9-1554-4d23-a4de-e1f269b4346c', 'e0000000-0000-0000-0000-000000000106', 'ar', 'شراء الملابس', 'اشترِ قميصًا: تحدّث عن المقاس واللون والسعر.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('4bc959c3-ad5d-4636-8550-86d08e7c14a8', 'e0000000-0000-0000-0000-000000000201', 'en', 'My daily routine', 'Write about what you do from the morning until the night.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('c06ff516-0273-4e08-b018-56d25e94a90e', 'e0000000-0000-0000-0000-000000000201', 'ar', 'روتيني اليومي', 'اكتب عمّا تفعله من الصباح حتى الليل.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('57f3cd73-bb8f-45b4-9519-b7005765d0ea', 'e0000000-0000-0000-0000-000000000202', 'en', 'My best friend', 'Describe your best friend and what you do together.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('e25e68f7-e195-4688-90d5-dd4162a29e1c', 'e0000000-0000-0000-0000-000000000202', 'ar', 'صديقي المفضل', 'صِف صديقك المفضل وما تفعلانه معًا.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
	('cdb3ffe6-1588-4f14-ba61-c1493abdd93c', 'e0000000-0000-0000-0000-000000000203', 'en', 'My family', 'Write about the people in your family.', '2026-11-02 23:26:59.261209+00', '2026-11-02 23:26:59.261209+00'),
