	('4ddd6522-47a3-5ae3-a060-4956acb72c3c', '53eac80d-8ee5-5b0e-be19-c581b37ba72e', 'Should you require any further information, please do not hesitate to contact us.', NULL, true, 0, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
	('b47cc762-3043-5634-a605-9c45abb90fed', '53eac80d-8ee5-5b0e-be19-c581b37ba72e', 'If you want info, call us.', NULL, false, 1, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
