	('58aae803-491e-5c35-9b01-8de56487c723', 'a58e3dcd-023f-539d-a031-aade3ab42308', 'Were the proposal to be accepted, we would proceed immediately.', NULL, true, 0, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
	('c9e46d92-c388-589b-9d51-0829469469ac', 'a58e3dcd-023f-539d-a031-aade3ab42308', 'If they accept the proposal, we proceed.', NULL, false, 1, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
	('78a486e8-a8d4-5847-88c3-364d796e100e', 'a58e3dcd-023f-539d-a031-aade3ab42308', 'If the proposal accepted, we go.', NULL, false, 2, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
	('38fd84c4-0b71-5770-9a9a-4a08391e400b', 'a58e3dcd-023f-539d-a031-aade3ab42308', 'Accept, we proceed.', NULL, false, 3, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
	('f2f40e46-741d-559d-9f00-8bb24ffa5c13', 'bcc85a20-cdb4-5986-a308-ec6350ecf7d3', 'Had we anticipated the delay, we would have informed you.', NULL, true, 0, NULL, '2026-11-09 22:37:41.062435+00', '2026-11-09 22:37:41.062435+00'),
