	('1cf48f9b-7ccc-4093-a20a-c9db4f4350be', 'especially', 'خصوصًا', 'I love fruit, especially mangoes.', 'adverb', 'intermediate', 96, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('577ddd78-457a-4b55-8168-f3d43b5db49b', 'although', 'رغم أن', 'Although it was raining, we went out.', 'conjunction', 'intermediate', 97, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('4abdadfe-58e5-4451-bf15-dc1c5163a76d', 'however', 'لكن', 'I like the flat. However, it is too expensive.', 'adverb', 'intermediate', 98, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('37a1d5d1-ed16-48a3-bdfe-1ebffc9bbf56', 'instead', 'بدلًا من ذلك', 'There was no bus, so we walked instead.', 'adverb', 'intermediate', 99, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00');
INSERT INTO public.vocabulary_words (id, word, translation_ar, example_sentence, part_of_speech, level, sort_order, is_active, created_at, updated_at) VALUES
	('777ad2dd-594b-49d8-8a0b-924afc407a11', 'achieve', 'يحقّق', 'She worked hard to achieve her goal.', 'verb', 'advanced', 100, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('46f1b09e-f721-45c9-954a-e559d13844f3', 'consider', 'يأخذ في الاعتبار', 'Consider all the options before you choose.', 'verb', 'advanced', 101, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('2a1a859c-1825-459f-b7a9-36d50115b8ac', 'maintain', 'يحافظ على', 'It is important to maintain a healthy routine.', 'verb', 'advanced', 102, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('2cb7cb21-9895-48ad-a8a0-345fb4362dc0', 'rely', 'يعتمد', 'You can rely on me.', 'verb', 'advanced', 103, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('92e0b92e-5381-4ed3-80d1-58a1f5ee9b73', 'acquire', 'يكتسب', 'She acquired new skills at university.', 'verb', 'advanced', 104, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('0ac92433-79b9-4d5d-8e4f-225a470f3620', 'attempt', 'يحاول', 'He attempted to climb the mountain.', 'verb', 'advanced', 105, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c855d1b6-7ab4-4063-b0f6-341f92c3ab62', 'contribute', 'يساهم', 'Everyone can contribute to the project.', 'verb', 'advanced', 106, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('266d4a25-8627-4480-80f6-d4dc67cdeae0', 'demonstrate', 'يُظهر', 'The experiment demonstrates the idea clearly.', 'verb', 'advanced', 107, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('35ee4192-8ec4-4b3b-8768-8b63a60dc8cb', 'emphasize', 'يؤكّد على', 'The teacher emphasized the importance of practice.', 'verb', 'advanced', 108, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c41945c2-3f5a-4598-9ac3-43880985b05d', 'establish', 'يؤسّس', 'They established the company in 1998.', 'verb', 'advanced', 109, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('9d74e443-5ca8-4294-a61c-0127de51ac54', 'estimate', 'يُقدّر', 'Experts estimate that prices will rise.', 'verb', 'advanced', 110, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('6887839d-c38e-4d8c-876e-05f36354e295', 'overcome', 'يتغلّب على', 'She wants to overcome her fear of public speaking.', 'verb', 'advanced', 111, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('662a60cf-5306-4b36-8fb8-b8f080dfca32', 'persuade', 'يُقنع', 'He persuaded me to join the team.', 'verb', 'advanced', 112, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('1ec8b208-fea2-447a-8857-445a1e2e6337', 'postpone', 'يؤجّل', 'The meeting was postponed until Friday.', 'verb', 'advanced', 113, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('4f9f4cbd-e4b5-48e5-8bb7-e25d6bb7e5e1', 'struggle', 'يكافح', 'Many students struggle with grammar.', 'verb', 'advanced', 114, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('78fba2c8-fd47-4e91-b43c-4a62afc10df3', 'reluctant', 'متردد', 'She was reluctant to speak in public.', 'adjective', 'advanced', 115, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('aece0e48-57f4-409a-ae97-5d4cdbcde542', 'essential', 'أساسي', 'Water is essential for life.', 'adjective', 'advanced', 116, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('af369e7e-e9b8-4088-80d4-e8c53b0c13cb', 'significant', 'مهم', 'There was a significant change in the results.', 'adjective', 'advanced', 117, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('389ac2da-e5e8-4e8a-82b3-cdbdb5172a8e', 'sufficient', 'كافٍ', 'We don''t have sufficient time.', 'adjective', 'advanced', 118, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('f154f77f-f59a-4196-81f5-ed67ff444b8f', 'ambitious', 'طموح', 'He is an ambitious young engineer.', 'adjective', 'advanced', 119, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('7c30d3c3-7426-4695-bd41-c8d4ae153f04', 'flexible', 'مرن', 'My working hours are flexible.', 'adjective', 'advanced', 120, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('b2dbf0c1-e09c-4cc5-8d41-2df06c641600', 'reasonable', 'معقول', 'The price seems reasonable.', 'adjective', 'advanced', 121, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('5dd71098-4191-4298-bb60-d1c5dbd8c791', 'genuine', 'حقيقي', 'It is a genuine leather bag.', 'adjective', 'advanced', 122, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('15fd93cb-1e05-4a61-aa91-7d27df2b8fff', 'inevitable', 'لا مفرّ منه', 'Change is inevitable.', 'adjective', 'advanced', 123, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('5d12c575-44ae-4c34-ba37-4d8785efd8a1', 'ethical', 'أخلاقي', 'It is not ethical to copy other people''s work.', 'adjective', 'advanced', 124, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('32b7b197-5e07-4810-b301-27c9b1e12980', 'obvious', 'واضح', 'The answer is obvious.', 'adjective', 'advanced', 125, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c6cccc65-fd22-48e8-b529-6f9b74328652', 'challenge', 'تحدٍّ', 'Learning a language is a big challenge.', 'noun', 'advanced', 126, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('d1e0460a-3068-4c23-9eb1-07359b220a46', 'achievement', 'إنجاز', 'Graduating was her greatest achievement.', 'noun', 'advanced', 127, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('7fe68ac2-0a2a-416c-bbaf-ffc3d7cd94a7', 'assumption', 'افتراض', 'You should not make assumptions.', 'noun', 'advanced', 128, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('09535cee-296e-43c4-8cf9-28930767c13f', 'behaviour', 'سلوك', 'The teacher praised the children''s behaviour.', 'noun', 'advanced', 129, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('98fe5167-84dc-447c-93e0-fa7b143a395f', 'benefit', 'فائدة', 'Exercise has many health benefits.', 'noun', 'advanced', 130, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c43f7b77-4a39-4609-888e-258bffa2b9ad', 'consequence', 'عاقبة', 'Every action has a consequence.', 'noun', 'advanced', 131, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c9cb2562-e3ca-40a7-addb-630746d9cc84', 'criticism', 'نقد', 'He accepted the criticism calmly.', 'noun', 'advanced', 132, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('b44f692f-0758-476a-a80f-fce9a7081c76', 'evidence', 'دليل', 'There is no evidence to support this idea.', 'noun', 'advanced', 133, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('f4c157c3-a7eb-4089-a21c-33e2d9891843', 'influence', 'تأثير', 'Parents have a strong influence on children.', 'noun', 'advanced', 134, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('32e72c10-a322-42f6-822b-6773ae4f06b2', 'priority', 'أولوية', 'Safety is our top priority.', 'noun', 'advanced', 135, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('23302f1c-2420-400c-b7ee-10a16dd1bd2e', 'responsibility', 'مسؤولية', 'Taking care of a pet is a big responsibility.', 'noun', 'advanced', 136, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('a06ac6be-7de3-46d2-9d62-1a418bc37f29', 'solution', 'حل', 'We need to find a solution to this problem.', 'noun', 'advanced', 137, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('760ad104-956b-47f1-91af-45c4905b8cf7', 'approach', 'أسلوب', 'A new approach to teaching can help.', 'noun', 'advanced', 138, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('068859ab-af69-4b1a-8bca-7bd6f52d7f1b', 'attitude', 'موقف', 'A positive attitude helps you learn.', 'noun', 'advanced', 139, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('01dad78a-25cc-4790-b127-eda4ec9d1f79', 'resource', 'مورد', 'Water is a precious resource.', 'noun', 'advanced', 140, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('dac50ea1-3dfa-4c2f-8fca-f33a0d589bc4', 'nevertheless', 'ومع ذلك', 'It was raining; nevertheless, we went out.', 'adverb', 'advanced', 141, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('3e35e5af-973e-4627-acaf-c657fdcc0186', 'furthermore', 'علاوة على ذلك', 'The plan is cheap; furthermore, it is safe.', 'adverb', 'advanced', 142, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('ec995881-e71f-4580-9990-d10f6246375e', 'therefore', 'لذلك', 'He was ill; therefore, he stayed home.', 'adverb', 'advanced', 143, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('556d3fd7-e69b-4d51-95ea-c53c059148e2', 'gradually', 'تدريجيًا', 'Gradually, her English improved.', 'adverb', 'advanced', 144, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('6ab7e620-bff1-45d0-aa2c-00218285778d', 'definitely', 'بالتأكيد', 'I will definitely come to the party.', 'adverb', 'advanced', 145, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('c9a33184-07a0-4bbd-ae40-f3251ee8ce19', 'approximately', 'تقريبًا', 'The trip takes approximately two hours.', 'adverb', 'advanced', 146, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00'),
	('6156b380-dd53-46b5-9c68-a57f44d226f2', 'whereas', 'بينما', 'He likes tea, whereas she prefers coffee.', 'conjunction', 'advanced', 147, true, '2026-11-09 23:10:18.091889+00', '2026-11-09 23:10:18.091889+00');
